use std::{fs,io::{Read,Write},path::Path,process::{Command,Stdio},os::{fd::AsRawFd,unix::process::CommandExt}};
use serde_json::{json,Value};
type R<T>=Result<T,Box<dyn std::error::Error>>;
static ACTIVE:std::sync::OnceLock<std::sync::Mutex<std::collections::HashSet<String>>>=std::sync::OnceLock::new();
fn active()->&'static std::sync::Mutex<std::collections::HashSet<String>>{ACTIVE.get_or_init(||std::sync::Mutex::new(std::collections::HashSet::new()))}
pub struct Reservation(Vec<String>);
impl Drop for Reservation{fn drop(&mut self){if let Ok(mut active)=active().lock(){for id in &self.0{active.remove(id);}}}}
pub fn reserve(ids:Vec<String>)->Result<Reservation,String>{let mut current=active().lock().map_err(|_|"transfer unavailable")?;if ids.iter().any(|id|current.contains(id)){return Err("workspace already transferring".into())}for id in &ids{current.insert(id.clone());}Ok(Reservation(ids))}
pub fn busy(id:&str)->bool{active().lock().map_or(true,|current|current.contains(id))}
// The child changes its own cwd to the already-open selected directory before exec.
pub fn run(dir:&fs::File,request:&Value)->R<(u16,Value)>{let fd=dir.as_raw_fd();let mut command=Command::new(std::env::current_exe()?);command.arg("--portable-worker").stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::null());unsafe{command.pre_exec(move||{if libc::fchdir(fd)!=0{Err(std::io::Error::last_os_error())}else{Ok(())}});}let mut child=command.spawn()?;let data=serde_json::to_vec(request)?;child.stdin.take().ok_or("worker unavailable")?.write_all(&data)?;let output=child.wait_with_output()?;if !output.status.success(){return Err("transfer worker failed".into())}let value:Value=serde_json::from_slice(&output.stdout)?;Ok((value["status"].as_u64().ok_or("invalid worker response")? as u16,value["body"].clone()))}
pub fn child()->R<()> {let mut input=String::new();std::io::stdin().read_to_string(&mut input)?;let v:Value=serde_json::from_str(&input)?;let result=execute(&v);let (status,body)=match result{Ok(v)=>v,Err(e)=>(500,json!({"error":format!("Не удалось выполнить перенос: {e}")}))};println!("{}",json!({"status":status,"body":body}));Ok(())}
fn execute(v:&Value)->R<(u16,Value)> {match v["operation"].as_str(){
 Some("export")=>{let sources=v["sources"].as_array().ok_or("invalid sources")?;let nonce=uuid::Uuid::new_v4().simple().to_string();let stage=format!(".atlas-export-{nonce}");let target=format!("Atlas-{nonce}");fs::create_dir(&stage)?;let result=(||->R<()>{for (i,source) in sources.iter().enumerate(){let source=Path::new(source.as_str().ok_or("invalid source")?);atlas_native_storage_contract::snapshot_workspace(source,&Path::new(&stage).join(format!("workspace-{}",i+1)))?;}fs::File::open(&stage)?.sync_all()?;atlas_native_storage_contract::publish_snapshot(Path::new(&stage),Path::new(&target))?;Ok(())})();if let Err(e)=result{let _=fs::remove_dir_all(&stage);return Err(e)}let warning=if fs::File::open(".").and_then(|f|f.sync_all()).is_err(){Some("Копия создана, но не удалось подтвердить сохранение на диске.")}else{None};Ok((200,json!({"folder":target,"warning":warning})))}
 Some("snapshot-one")=>{let source=Path::new(".");if !super::valid_workspace(source){return Err("invalid workspace".into())}let name=[".workspace.json",".atlas-workspace.json"].iter().find_map(|n|fs::read(source.join(n)).ok().and_then(|s|serde_json::from_slice::<Value>(&s).ok()).and_then(|v|v["name"].as_str().map(str::to_owned))).unwrap_or_else(||"Импортированное пространство".into()).chars().take(100).collect::<String>();let id=v["id"].as_str().ok_or("invalid id")?;let dest=Path::new(v["destination"].as_str().ok_or("invalid destination")?);atlas_native_storage_contract::snapshot_workspace_named(source,dest,Some(&name))?;Ok((201,json!({"id":id,"name":name})))}
 Some("import")=>{let selected=Path::new(".");let mut inputs=Vec::new();if super::valid_workspace(selected){inputs.push(std::path::PathBuf::from("."));}else{for entry in fs::read_dir(selected)?{let entry=entry?;let name=entry.file_name();let name=name.to_string_lossy();if name.starts_with("workspace-")&&name[10..].chars().all(|c|c.is_ascii_digit())&&!name[10..].is_empty(){if entry.file_type()?.is_symlink()||!entry.file_type()?.is_dir()||!super::valid_workspace(&entry.path()){return Err("Некорректная папка пространства в наборе".into())}inputs.push(entry.path())}}inputs.sort();if inputs.is_empty()||inputs.len()>100{return Ok((400,json!({"error":"Выберите папку пространства Atlas или сохранённый набор"})))}}
  let root=Path::new(v["root"].as_str().ok_or("invalid root")?);let nonce=uuid::Uuid::new_v4().simple().to_string();let stage=root.join(format!(".atlas-import-{nonce}"));let target=root.join(format!("batch-{nonce}"));fs::create_dir(&stage)?;let result=(||->R<Vec<Value>>{use std::os::unix::fs::OpenOptionsExt;let mut created=Vec::new();for source in &inputs{let fd=fs::OpenOptions::new().read(true).custom_flags(libc::O_NOFOLLOW|libc::O_DIRECTORY).open(source)?;let id=uuid::Uuid::new_v4().simple().to_string();let (status,value)=run(&fd,&json!({"operation":"snapshot-one","destination":stage.join(&id).to_str().ok_or("invalid destination")?,"id":id}))?;if status!=201{return Err(value["error"].as_str().unwrap_or("Не удалось импортировать пространство").to_owned().into())}created.push(value);}fs::write(stage.join(".atlas-import-batch"),b"atlas-import-v1")?;fs::File::open(stage.join(".atlas-import-batch"))?.sync_all()?;fs::File::open(&stage)?.sync_all()?;atlas_native_storage_contract::publish_snapshot(&stage,&target)?;Ok(created)})();let created=match result{Ok(v)=>v,Err(e)=>{let _=fs::remove_dir_all(&stage);return Err(e)}};let warning=if fs::File::open(root).and_then(|f|f.sync_all()).is_err(){Some("Копия создана, но не удалось подтвердить сохранение на диске.")}else{None};Ok((201,json!({"workspaces":created,"warning":warning})))}
 _=>Err("invalid operation".into())}}
